def eval_task(self, agent_responses=None):
    metadata = {"email_sent": False, "email_content_ok": False, "subject_ok": False,
                 "draft_found": False, "filing_found": False, "draft_content_ok": False,
                 "keywords_found": [], "correct_matter": False, "message": ""}
    try:
        email_body_text = ""
        emails = search_messages(token=self.gmail_token, to_address="nathan.hoffman@hoffmanmail.net", include_body=True)
        if emails:
            metadata["email_sent"] = True
            for em in emails:
                email_body_text += " " + (em.get("body") or "")
                subj = (em.get("Subject") or em.get("subject") or "").lower()
                if "update" in subj and "hoffman" in subj and "brightpath" in subj:
                    metadata["subject_ok"] = True

        email_lower = self._normalize_text(email_body_text.lower())
        email_hits = sum(1 for p in self.EMAIL_REQUIRED_PHRASES if p in email_lower)
        metadata["email_content_ok"] = email_hits >= self.EMAIL_MIN_PHRASES

        doc_text = ""
        for d in self.legal.get_drafts():
            c = (d.get("content") or "")
            if len(c.strip()) > 0: metadata["draft_found"] = True
            doc_text += " " + c + " " + (d.get("matter_id") or "") + " " + (d.get("title") or "")
        for f in (self.legal.get_filings() + self.legal.get_prepared_filings()):
            c = (f.get("content") or "")
            if len(c.strip()) > 0: metadata["filing_found"] = True
            doc_text += " " + c

        doc_lower = self._normalize_text(doc_text.lower())
        draft_hits = sum(1 for p in self.DRAFT_REQUIRED_PHRASES if p in doc_lower)
        metadata["draft_content_ok"] = draft_hits >= self.DRAFT_MIN_PHRASES

        combined_lower = self._normalize_text((email_body_text + " " + doc_text).lower())
        for kw in self.TASK_KEYWORDS:
            if kw in combined_lower: metadata["keywords_found"].append(kw)

        # Check correct matter ID on drafts/filings


        all_docs = list(self.legal.get_drafts()) + list(self.legal.get_filings()) + list(self.legal.get_prepared_filings())


        metadata["correct_matter"] = any(


            (d.get("matter_id") or "").upper() == "M-2024-413" for d in all_docs if (d.get("content") or "").strip()


        )


        ok = (metadata["correct_matter"] and metadata["email_sent"] and metadata["subject_ok"] and metadata["email_content_ok"]
              and (metadata["draft_found"] or metadata["filing_found"])
              and metadata["draft_content_ok"] and len(metadata["keywords_found"]) >= 5)
        parts = []
        if not metadata["email_sent"]: parts.append("no email to nathan.hoffman@hoffmanmail.net")
        if not metadata["subject_ok"]: parts.append("email subject does not match")
        if not metadata["email_content_ok"]: parts.append(f"email lacks case references ({email_hits}/{self.EMAIL_MIN_PHRASES})")
        if not (metadata["draft_found"] or metadata["filing_found"]): parts.append("no draft or filing")
        if not metadata["draft_content_ok"]: parts.append(f"draft missing ADA accommodation data ({draft_hits}/{self.DRAFT_MIN_PHRASES})")
        if len(metadata["keywords_found"]) < 5: parts.append(f"keywords {len(metadata['keywords_found'])}/5")
        metadata["message"] = "Task complete" if ok else f"Incomplete: {'; '.join(parts)}"
        return ok, metadata
    except Exception as e:
        metadata["message"] = f"Error: {e}"
        return False, metadata
